# Let's correctly apply the transformation by converting the entire hex string to a single decimal number

# Function to convert an arithmetic expression to its hexadecimal representation (without spaces)
def expression_to_hex(expression):
    return "".join(format(ord(char), 'X') for char in expression)

# Function to convert the full hexadecimal string to decimal
def hex_string_to_decimal(hex_string):
    return int(hex_string, 16)

# Define test cases
test_cases = ["2+1=", "4+5=", "6+3=", "8+1="]

# Store results
results = {}

for case in test_cases:
    hex_representation = expression_to_hex(case)  # Convert entire expression to hex
    decimal_representation = hex_string_to_decimal(hex_representation)  # Convert hex to decimal
    last_digit = decimal_representation % 10  # Extract last digit
    results[case] = {
        "Hex": hex_representation,
        "Decimal": decimal_representation,
        "Last Digit": last_digit
    }

# Display results
df_results = pd.DataFrame.from_dict(results, orient='index')
tools.display_dataframe_to_user(name="Hex Encoding to Decimal Results", dataframe=df_results)

